function readContext(): string {
  const user = session.current();
  return JSON.stringify([session.contextVersion(), user?.id, user?.scope, user?.tenantId, user?.role, user?.status]);
}
export function useRead<T>(path: string | null, revision = 0, retainTransientError = false) {
  const [, sessionChanged] = useState(0);
  useEffect(() => session.subscribe(() => sessionChanged(v => v + 1)), []);
  const context = readContext();
  const parameters = new URLSearchParams(path?.split('?')[1]);
  const resource = path === null ? null : `${path.split('?')[0]}|${parameters.get('tenantId') ?? ''}|${parameters.get('globalOnly') ?? ''}`;
  const [result, setResult] = useState<{ context: string; resource: string | null; path: string | null; revision: number; data: T | null; error: FeedbackError; status: number | null; pending: boolean } | null>(null);
  const sameContext = result?.context === context && result?.resource === resource;
  const currentRequest = sameContext && result?.path === path && result?.revision === revision;
  const data = sameContext ? result!.data : null;
  const error = currentRequest ? result!.error : '';
  const pending = path !== null && (!currentRequest || result!.pending);
  useEffect(() => {
    let alive = true;
    setResult(old => ({ context, resource, path, revision,
      data: old?.context === context && old?.resource === resource ? old.data : null,
      error: '', status: null, pending: path !== null }));
    if (path) void session.request<T>(path).then(data => {
      if (alive && readContext() === context) setResult({ context, resource, path, revision, data, error: '', status: null, pending: false });
    }).catch(e => {
      if (alive && readContext() === context) setResult(old=>({ context, resource, path, revision, data: retainTransientError&&!(e instanceof ApiFailure&&[401,403,404].includes(e.status))&&old?.context===context&&old?.resource===resource?old.data:null,
        error: e instanceof ApiFailure ? e : 'REQUEST_FAILED', status: e instanceof ApiFailure ? e.status : null, pending: false }));
    });
    return () => { alive = false; };
  }, [path, revision, context, retainTransientError]);
  return { data, error, status: currentRequest ? result!.status : null, pending, updating: pending && data !== null };
}
