 const clearAudit=(key:keyof AuditFilters)=>{setFilters(old=>({...old,[key]:''}));if(key==='tenant'){if(applied.tenantId!==undefined||applied.globalOnly!==undefined){setApplied(old=>({...old,tenantId:undefined,globalOnly:undefined}));paginate(0);}}else{const field=({type:'targetType',target:'targetId',actor:'actorId'} as Partial<Record<keyof AuditFilters,keyof AuditQuery>>)[key]??key as keyof AuditQuery;if(applied[field]!==undefined){setApplied(old=>({...old,[field]:undefined}));paginate(0);}}setProblem('');};
