 for(const [key,value] of Object.entries(applied))if(value!==undefined)q.set(key,String(value));
 const {data,error,pending}=useRead<{items:AuditItem[];page:number;size:number;totalElements:number}>(`/api/v1/audit-log?${q}`),detail=useRead<AuditItem>(id?`/api/v1/audit-log/${id}`:null);
