 return <div role="alert" className="error-box" data-http-status={status} data-error-code={code&&/^[A-Z][A-Z0-9_]{0,63}$/.test(code)?code:undefined}><p>{feedback.message}</p>{feedback.uncertain&&<p className="mt-2 text-sm">{t('f4.uncertain')}</p>}{retainInput&&<p className="mt-2 text-xs">{t('f4.sameSession')}</p>}{reload&&feedback.review&&<Button type="button" variant="outline" className="mt-3" onClick={reload}>{t('ui.reloadLatestState')}</Button>}</div>;
